import pandas as pd,pathlib,html,json,hashlib,numpy as np
r=pathlib.Path('/home/xiaolv/code/a_share/topics/02_AFML_BIG_WINNER/experiments/pending/35_industry_rise_mechanisms_and_rotation');out=r/'reports/results_asof_r307_20261114/l3_monthly_holdings';out.mkdir(exist_ok=True)
def pick(p):return p[(p.era=='SW2021')&(p.level=='L3')&(p.cohort=='core__rank__FD__F')&(p.horizon==20)&(p.method=='base')].copy()
hp=r/'outputs/r210/holdings.parquet';pp=r/'outputs/r210/mapped_predictions.parquet';ip=r/'outputs/r210/intervals.csv';npth=pathlib.Path('/home/xiaolv/.cache/a_share/ep32/forecast_v5/daily_industries.parquet')
p=pick(pd.read_parquet(hp));q=pd.read_parquet(npth,columns=['era','level','industry_code','industry_name']);q=q[(q.era=='SW2021')&(q.level=='L3')][['industry_code','industry_name']].drop_duplicates();p=p.merge(q,on='industry_code',validate='many_to_one');pred=pick(pd.read_parquet(pp)).rename(columns={'date':'origin'});assert not pred.duplicated(['origin','industry_code']).any();p=p.merge(pred[['origin','industry_code','prediction']],on=['origin','industry_code'],validate='one_to_one');it=pick(pd.read_csv(ip));it.origin=pd.to_datetime(it.origin);p=p.merge(it[['origin','entry','exit','selected','universe']],on='origin',validate='many_to_one')
sections=[];txt=[];records=[];alltops=[]
for d,g in p.groupby('origin',sort=True):
 g=g.sort_values(['prediction','industry_code'],ascending=[False,True]);assert len(g)==g.selected.iloc[0]==53 and np.allclose(g.weight,1/53);assert abs(g.weight.sum()-1)<1e-10
 universe=pred[pred.origin.eq(d)].sort_values(['prediction','industry_code'],ascending=[False,True]);assert set(g.industry_code)==set(universe.head(53).industry_code)
 month=g.entry.iloc[0][:7];title=f'{month}｜信号日 {d.date()}｜持仓 {g.entry.iloc[0]} 至 {g.exit.iloc[0]}｜53个行业'
 rows=[];textrows=[]
 for i,(_,x) in enumerate(g.iterrows(),1):
  z={'holding_month':month,'signal_date':str(d.date()),'entry':x.entry,'exit':x.exit,'selected_rank':i,'industry_code':x.industry_code,'industry_name':x.industry_name,'weight':float(x.weight),'prediction_score':float(x.prediction)};records.append(z)
  rows.append(f'<tr><td>{i}</td><td>{html.escape(x.industry_name)}</td><td>{html.escape(x.industry_code)}</td><td>{x.weight:.4%}</td><td>{x.prediction:.6f}</td></tr>');textrows.append(f'{i:02d}. {x.industry_name}（{x.industry_code}） 权重{x.weight:.4%} 分数{x.prediction:.6f}')
 sections.append(f'<details open><summary>{title}</summary><table><thead><tr><th>预测名次</th><th>行业</th><th>代码</th><th>调仓目标权重</th><th>预测分数</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></details>');txt.extend([title,*textrows,'']);alltops.append(f"| {month} | {'、'.join(g.industry_name.head(5))} |")
assert len(records)==1696
header='三级行业逐月完整持仓：价格特征F、收益排名目标、base；FD数据可用母体；SW2021；20日目标。对应年化18.85%的历史曲线。每月53个行业等权，名单按预测分数降序；分数不是收益率或概率。这里只提取历史结果，研究目标仍暂停。'
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>三级行业32期完整持仓</title><style>body{font:16px/1.65 system-ui,sans-serif;max-width:1050px;margin:30px auto;padding:0 18px;color:#172033}h1{font-size:26px}summary{cursor:pointer;font-weight:650;padding:14px;background:#edf2f7}details{margin:16px 0;border:1px solid #d9e1eb}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:8px 12px;border-bottom:1px solid #e6eaf0}th{background:#f8fafc}input{font:inherit;padding:8px;width:90%;max-width:650px}button{font:inherit;padding:7px;margin:8px 5px 0 0}@media print{input,button{display:none}}</style><h1>三级行业：32期完整入选名单</h1><p>'''+html.escape(header)+'''</p><p>实际持仓区间：2024-02-01至2026-10-08。共1,696条记录。名称来自归档行业字典；“Ⅲ”保留原名称。</p><input id="q" placeholder="搜索月份、行业名称或代码，例如 2026-09、半导体、851"><br><button onclick="document.querySelectorAll('details').forEach(x=>x.open=true)">展开全部</button><button onclick="document.querySelectorAll('details').forEach(x=>x.open=false)">收起全部</button>'''+''.join(sections)+'''<script>document.getElementById('q').addEventListener('input',e=>{let q=e.target.value.trim().toLowerCase();document.querySelectorAll('details').forEach(d=>{let all=d.querySelector('summary').textContent.toLowerCase().includes(q),n=0;d.querySelectorAll('tbody tr').forEach(r=>{let yes=!q||all||r.textContent.toLowerCase().includes(q);r.hidden=!yes;if(yes)n++});d.hidden=!n;if(q&&n)d.open=true})})</script></html>'''
(out/'holdings.html').write_text(page);(out/'holdings.txt').write_text(header+'\n\n'+'\n'.join(txt));(out/'holdings.json').write_text(json.dumps(records,ensure_ascii=False,indent=2));(out/'verification.json').write_text(json.dumps({'status':'PASS','months':32,'holdings':len(records),'per_month':53,'weight_sum_each_month':1,'selected_set_equals_top53_predictions':True,'goal_remains_paused':True,'input_sha256':{str(f):hashlib.sha256(f.read_bytes()).hexdigest()for f in [hp,pp,ip,npth]}},ensure_ascii=False,indent=2));print('\n'.join(alltops));print('output',out)
